mapper.select:
SELECT FROM ( SELECT COALESCE(instance.definition_id, instance.process_def_key) AS definition, COALESCE(definition.process_name, instance.process_def_key) AS definition_name, instance.status, DATE(instance.start_time) AS business_date, instance.dept_id AS department, department.dept_name AS department_name, instance.instance_id AS instance_count, CASE WHEN instance.status IN ('PASSED', 'AUTO_PASSED', 'REJECTED', 'TERMINATED', 'INVALIDATED', 'CANCELLED') AND instance.end_time >= instance.start_time THEN TIMESTAMPDIFF(SECOND, instance.start_time, instance.end_time) ELSE NULL END AS duration_seconds, 0 AS integrity_error FROM wf_process_instance instance LEFT JOIN wf_process_definition definition ON definition.definition_id = instance.definition_id AND definition.tenant_id = instance.tenant_id LEFT JOIN sys_dept department ON department.dept_id = instance.dept_id AND department.tenant_id = instance.tenant_id WHERE instance.tenant_id = #{tenantId} AND instance.deleted = 0 AND instance.start_time >= #{query.startDate} AND instance.start_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
AND (instance.start_user_id = #{userId} OR EXISTS(SELECT 1 FROM wf_task task WHERE task.tenant_id = instance.tenant_id AND task.instance_id = instance.instance_id AND task.assignee = #{userId}) OR EXISTS(SELECT 1 FROM wf_task_history history WHERE history.tenant_id = instance.tenant_id AND history.instance_id = instance.instance_id AND (history.operator_id = #{userId} OR history.on_behalf_of_user_id = #{userId})) OR EXISTS(SELECT 1 FROM wf_process_copy copy WHERE copy.tenant_id = instance.tenant_id AND copy.instance_id = instance.instance_id COLLATE utf8mb4_general_ci AND copy.user_id = #{userId}) OR instance.instance_id IN #{instanceId} )
) fact
